import numpy as np
from PIL import Image, ImageFilter
from collections import deque
def key(a, tol=22):
    h,w=a.shape[:2]; rgb=a[:,:,:3].astype(int)
    border=np.concatenate([rgb[0],rgb[-1],rgb[:,0],rgb[:,-1]]); bg=np.median(border,axis=0)
    near=np.abs(rgb-bg).max(axis=2)<=tol
    m=np.zeros((h,w),bool); q=deque()
    for x in range(w):
        for y in (0,h-1):
            if near[y,x] and not m[y,x]: m[y,x]=True; q.append((y,x))
    for y in range(h):
        for x in (0,w-1):
            if near[y,x] and not m[y,x]: m[y,x]=True; q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and near[ny,nx] and not m[ny,nx]: m[ny,nx]=True; q.append((ny,nx))
    al=np.asarray(Image.fromarray(np.where(m,0,255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(0.8)))
    out=a.copy(); out[:,:,3]=al; return out
def frames(src, cols, rows, names):
    im=np.asarray(Image.open(src).convert('RGBA')); H,W=im.shape[:2]
    cells=[]
    for r in range(rows):
        for c in range(cols):
            cell=key(im[r*H//rows:(r+1)*H//rows, c*W//cols:(c+1)*W//cols].copy())
            ys,xs=np.nonzero(cell[:,:,3]>40)
            # largest-ish: drop stray specks by bbox of pixels
            cells.append((cell, ys.min(), ys.max(), xs.min(), xs.max(), xs.mean()))
    # common canvas: align feet (bottom) and horizontal centre of mass
    hmax=max(c[2]-c[1] for c in cells)+8; wmax=max(max(c[5]-c[3], c[4]-c[5]) for c in cells)*2+8
    for (cell,y0,y1,x0,x1,cx),n in zip(cells,names):
        canvas=np.zeros((int(hmax),int(wmax),4),np.uint8)
        top=int(hmax-4-(y1-y0)); left=int(wmax/2-(cx-x0))
        canvas[top:top+y1-y0+1, left:left+x1-x0+1]=cell[y0:y1+1,x0:x1+1]
        Image.fromarray(canvas).resize((int(wmax*0.8),int(hmax*0.8)),Image.LANCZOS).save(f'public/assets/runner/{n}.png',optimize=True)
